  const search = (args.search ?? "").trim().toLowerCase();
  const rows = sourceRows.slice(0, 2000).filter(row => (row.companyId ? access.companyIds.includes(row.companyId) : access.companyIds.length === 6) && (args.companyId !== "unassigned" || !row.companyId) && Boolean(row.deletedAt) === Boolean(args.trashed) && (!args.status || args.status === "all" || row.status === args.status) && (!args.direction || args.direction === "all" || row.direction === args.direction) && (!args.source || args.source === "all" || row.source === args.source) && (!args.currency || args.currency === "all" || row.currency === args.currency) && (!args.from || row.date >= args.from) && (!args.to || row.date <= args.to) && (!search || [row.description, row.counterparty, row.reference, row.account, row.cardLastFour, row.source].join(" ").toLowerCase().includes(search)));
  const sort = statementSortKeys.find(key => key === args.sort) ?? "date", order = args.order === "asc" ? 1 : -1;
  rows.sort((a, b) => { const av = a[sort] ?? "", bv = b[sort] ?? ""; const amountA = sort === "amountMinor" ? BigInt(av) * 10n ** BigInt(8 - statementCurrencyScale(a.currency)) : 0n, amountB = sort === "amountMinor" ? BigInt(bv) * 10n ** BigInt(8 - statementCurrencyScale(b.currency)) : 0n; const result = sort === "amountMinor" ? (amountA < amountB ? -1 : amountA > amountB ? 1 : 0) : String(av).localeCompare(String(bv)); return order * result || a._id.localeCompare(b._id); });
