  const access = await member(ctx, args); manage(access); checkCompany(access, args.companyId); if (!/^\d{4}$/.test(args.lastFour) || args.lastFour === "1003" || !args.label.trim() || args.label.length > 100 || (args.source?.length ?? 0) > 100 || (args.account?.length ?? 0) > 512) throw new ConvexError("Enter a valid card label and four text digits");
