export const confirmImport = mutation({ args: { ...authArgs, id: v.id("statementImports"), reviewed: v.boolean() }, returns: v.null(), handler: async (ctx, args) => { const access = await member(ctx, args), row = await ctx.db.get(args.id); if (!row) throw new ConvexError("Import not found"); checkCompany(access, row.companyId); for (const item of row.rows) checkCompany(access, item.companyId); if (row.errors.length || !row.rows.length) throw new ConvexError("Correct every invalid row before importing"); if (!args.reviewed) throw new ConvexError("Review the original and preview before confirming"); if (row.status === "imported" || row.status === "importing") return null; await ctx.db.patch(args.id, { status: "importing", reviewed: true, error: undefined }); await audit(ctx, access.actor, "import", args.id, "confirmed"); await ctx.scheduler.runAfter(0, internal.statementProcessing.importBatch, { id: args.id }); return null; } });
